'use strict';
const t=OrionI18n.t;
function renderHub(){const earned=OrionProgress.read().sigils;document.getElementById('availability').textContent=t(`${ORION_MISSIONS.filter(m=>m.href).length} mission available · ${ORION_MISSIONS.length} stories to explore`,`${ORION_MISSIONS.filter(m=>m.href).length} 個任務已開放 · ${ORION_MISSIONS.length} 個故事等待探索`);document.getElementById('total').textContent=ORION_MISSIONS.filter(m=>earned.includes(m.sigil)).length;document.getElementById('sigils').innerHTML=ORION_MISSIONS.map(m=>{const yes=earned.includes(m.sigil),name=t(m.sigilEnglish,m.sigilName),state=yes?t('Collected','已收藏'):t('Not collected','未收藏');return `<div class="sigil ${yes?'earned':''}" aria-label="${name}: ${state}"><b aria-hidden="true">${m.symbol}</b>${name}<br>${state}</div>`}).join('');document.getElementById('missions').innerHTML=ORION_MISSIONS.map(m=>`<article class="mission ${m.href?'available':''}"><div class="mission-top"><span class="symbol" aria-hidden="true">${m.symbol}</span><span class="badge">${m.href?t('Available','已開放'):t('Coming soon','即將登場')}</span></div><h3>${t(m.english,m.title)}</h3><p class="story">${t(m.storyEnglish,m.story)}</p><div class="topic">${t(m.topic.split(' / ')[0],m.topic.split(' / ')[1])}</div><div class="card-footer"><span>${earned.includes(m.sigil)?t('✦ Collected','✦ 已收藏'):t(m.sigilEnglish+' Sigil',m.sigilName+'符印')}</span>${m.href?`<a href="${m.href}">${earned.includes(m.sigil)?t('Play again','再次探索'):t('Start mission','開始任務')} ↗</a>`:`<span class="soon">${t('In preparation','準備中')}</span>`}</div></article>`).join('');}
window.addEventListener('orion-language',renderHub);window.addEventListener('storage',renderHub);OrionI18n.apply();
